import re


def eval_expression(expr):
    """
    +, -, *, / と括弧を含む算術式を計算する。
    単項の + / - にも対応する。
    """

    # トークン化
    token_pattern = re.compile(
        r"\s*(?:(\d+(?:\.\d*)?|\.\d+)|([()+\-*/]))"
    )

    tokens = []
    pos = 0

    while pos < len(expr):
        match = token_pattern.match(expr, pos)

        if match is None:
            if expr[pos:].strip() == "":
                break
            raise ValueError(f"不正な文字があります: {expr[pos]!r}")

        number, operator = match.groups()

        if number is not None:
            value = float(number) if "." in number else int(number)
            tokens.append(("number", value))
        else:
            tokens.append((operator, operator))

        pos = match.end()

    tokens.append(("EOF", None))

    class Parser:
        def __init__(self, tokens):
            self.tokens = tokens
            self.index = 0

        def current(self):
            return self.tokens[self.index]

        def consume(self, kind=None):
            token = self.current()

            if kind is not None and token[0] != kind:
                raise ValueError(f"{kind!r} が必要です")

            self.index += 1
            return token

        # expression = term (("+" | "-") term)*
        def parse_expression(self):
            value = self.parse_term()

            while self.current()[0] in ("+", "-"):
                operator = self.consume()[0]
                right = self.parse_term()

                if operator == "+":
                    value += right
                else:
                    value -= right

            return value

        # term = unary (("*" | "/") unary)*
        def parse_term(self):
            value = self.parse_unary()

            while self.current()[0] in ("*", "/"):
                operator = self.consume()[0]
                right = self.parse_unary()

                if operator == "*":
                    value *= right
                else:
                    if right == 0:
                        raise ZeroDivisionError("division by zero")
                    value /= right

            return value

        # unary = ("+" | "-") unary | primary
        def parse_unary(self):
            if self.current()[0] == "+":
                self.consume("+")
                return self.parse_unary()

            if self.current()[0] == "-":
                self.consume("-")
                return -self.parse_unary()

            return self.parse_primary()

        # primary = number | "(" expression ")"
        def parse_primary(self):
            if self.current()[0] == "number":
                return self.consume("number")[1]

            if self.current()[0] == "(":
                self.consume("(")
                value = self.parse_expression()
                self.consume(")")
                return value

            raise ValueError("数値または '(' が必要です")

        def parse(self):
            result = self.parse_expression()

            if self.current()[0] != "EOF":
                raise ValueError("式の末尾に不正なトークンがあります")

            return result

    return Parser(tokens).parse()
